client_script:
// quick heal
$(document).on('focusout', '[data-fieldname="order_id"]', function() {
    var value = $(this).val();
    frappe.web_form.set_value('serial_no', '')
	if (value !== '' && value !== null) {
		frappe.call({
			method: 'nj_features.nj_features.web_form.quick_heal.quick_heal.check_order_id',
			args: {'order_id': value},
			callback: (r) => {
			    frappe.web_form.set_df_property('serial_no', 'read_only', 0);

                if (r && r.message !== undefined) {
                    if (r.message && r.message.length === 1) {
                        frappe.web_form.set_value('serial_no', r.message[0]);
                        frappe.web_form.set_df_property('serial_no', 'read_only', 1);
                    } else if (r.message.length > 1) {
                        const options = r.message.join('\n');
                        frappe.web_form.set_df_property('serial_no', 'options', options);
                        $('[data-fieldname="serial_no"]').focus().closest('.control-input').css({
                            'border-radius': '0.25rem',
                            'border': '2px solid #007bff'
                        });

                        frappe.show_alert({
                            message: __('Select Serial No(s)'),
                            indicator: 'green'
                        });
                    } else {
                        frappe.throw('No <b>Serial No.</b> found for <b>Order ID: '+frappe.web_form.get_value('order_id')+'</b>. <br>Please fill the Order ID correctly.')
                        return false;
    				}
    			} else {
                    frappe.throw('No <b>Serial No.</b> found for <b>Order ID: '+frappe.web_form.get_value('order_id')+'</b>. <br>Please fill the Order ID correctly.')
                    return false;
				}
			}
		})
	}
})

frappe.web_form.on('serial_no', (field, value)=> {
    var serial_no = frappe.web_form.get_value('serial_no');
	if (value !== '' && value !== null) {

		frappe.call({
			method: 'nj_features.nj_features.web_form.quick_heal.quick_heal.find_laptop_registration',
			args: {'serial_no': value},
			callback: (r) => {
				if (r.message == serial_no) {
				    frappe.web_form.set_value('serial_no', '');
				    frappe.throw('<b>Serial No. : '+serial_no+'</b> already registed with us!');
				    return false;
				} else {
				    frappe.web_form.set_value('naming_series','QH-.YYYY.-.MM.-')
				}
			}
		})
	}
})

$(document).on('focusout', '[data-fieldname="mobile_number"]', function() {
    var value = $(this).val();
	if (value !== '' && value !== null) {

		frappe.call({
			method: 'nj_features.nj_features.web_form.quick_heal.quick_heal.validate_phone_no',
			args: {'phone_no': value}
		})
	}
})
